  @Test
  void jsonRoundTrip() {
    LogRecord r =
        LogRecord.builder()
            .timestamp(Instant.parse("2026-01-02T03:04:05.000001Z"))
            .severity(Severity.WARN)
            .body("msg")
            .attributes(
                Map.of("n", 1, "f", 1.5, "b", true, "l", List.of("x"), "m", Map.of("k", "v")))
            .resource(Map.of("service.name", "svc"))
            .traceId(TRACE)
            .spanId(SPAN)
            .traceFlags(1)
            .build();
    String json = LogRecordJson.toJson(r);
    assertThat(json)
        .contains("\"severity\":13")
        .contains("\"timestamp\":\"2026-01-02T03:04:05.000001Z\"");
    LogRecord back = LogRecordJson.fromJson(json);
    assertThat(back.attributes()).isEqualTo(r.attributes());
    assertThat(back.traceId()).isEqualTo(r.traceId());
    assertThat(back.traceFlags()).hasValue(1);
    assertThat(LogRecordJson.byteSize(r)).isEqualTo(json.getBytes().length);
    // trace flags without trace id are not written
    assertThat(LogRecordJson.toMap(LogRecord.builder().traceFlags(1).build()))
        .doesNotContainKey("traceFlags");
  }

  @Test
  void jsonParsingVariants() {
    LogRecord a =
        LogRecordJson.fromJson(
            "{\"timestamp\":\"2026-01-02T03:04:05+01:00\",\"severityText\":\"warning\","
                + "\"body\":{\"k\":1},\"attributes\":{\"n\":null,\"big\":1e400,\"arr\":[1,2.5],"
                + "\"huge\":123456789012345678901234567890},\"traceFlags\":\"x\"}");
    assertThat(a.timestamp()).isEqualTo(Instant.parse("2026-01-02T02:04:05Z"));
    assertThat(a.severity()).isEqualTo(Severity.WARN);
    assertThat(a.severityText()).isEqualTo("warning");
    assertThat(a.body()).isEqualTo("{\"k\":1}");
    assertThat(a.attributes().get("n")).isEqualTo("");
    assertThat(a.attributes().get("arr")).isEqualTo(List.of(1L, 2.5d));
    assertThat(a.attributes().get("huge")).isInstanceOf(Double.class);
    assertThat(a.traceFlags()).isEmpty();
    LogRecord b =
        LogRecordJson.fromJson("{\"timestamp\":null,\"body\":null,\"severityText\":null}");
    assertThat(b.severity()).isEqualTo(Severity.INFO);
    assertThat(b.timestamp()).isEqualTo(Instant.EPOCH);
    LogRecord c = LogRecordJson.fromJson("{\"severityNumber\":17,\"attributes\":[]}");
    assertThat(c.severity()).isEqualTo(Severity.ERROR);
    LogRecord e =
        LogRecordJson.fromJson("{\"severity\":5,\"observedTimestamp\":\"2026-01-01T00:00:00Z\"}");
    assertThat(e.severity()).isEqualTo(Severity.DEBUG);
    assertThat(e.observedTimestamp()).contains(Instant.parse("2026-01-01T00:00:00Z"));
    assertThat(LogRecordJson.toMap(e)).containsEntry("observedTimestamp", "2026-01-01T00:00:00Z");
    assertThat(LogRecordJson.fromJson("{\"observedTimestamp\":null}").observedTimestamp())
        .isEmpty();
    assertThatThrownBy(() -> LogRecordJson.fromJson("{")).isInstanceOf(ValidationException.class);
    assertThatThrownBy(() -> LogRecordJson.fromJson("[]")).isInstanceOf(ValidationException.class);
    assertThatThrownBy(() -> LogRecordJson.fromJsonNode(null))
        .isInstanceOf(ValidationException.class);
    assertThatThrownBy(() -> LogRecordJson.fromJson("{\"timestamp\":\"yesterday\"}"))
        .isInstanceOf(ValidationException.class);
    assertThat(LogRecordJson.toAttrValue(null)).isEqualTo("");
    assertThat(
            LogRecordJson.toAttrValue(
                com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.binaryNode(
                    new byte[] {1})))
        .isEqualTo("AQ==");
  }

  @Test
  void smallValueTypes() {
    ExportResult ok = ExportResult.success(3);
    assertThat(ok.accepted()).isEqualTo(3);
    assertThat(ok.error()).isEmpty();
    ExportResult fail = ExportResult.failure(1, 2, new UnavailableException("down"));
    assertThat(fail.error()).isPresent();
    assertThat(new ExportResult(0, 0, null).error()).isEmpty();
    assertThatThrownBy(() -> new ExportResult(-1, 0, Optional.empty()))
        .isInstanceOf(IllegalArgumentException.class);
    assertThatThrownBy(() -> new ExportResult(0, -1, Optional.empty()))
        .isInstanceOf(IllegalArgumentException.class);
    assertThat(DropPolicy.BLOCK.wireValue()).isEqualTo("block");
    assertThat(DropReason.EXPORT_FAILED.wireValue()).isEqualTo("export_failed");
    assertThat(SortOrder.ASC.wireValue()).isEqualTo("asc");
    LogSearchResult res = new LogSearchResult(null, null, null);
    assertThat(res.records()).isEmpty();
    assertThat(res.nextCursor()).isEmpty();
    assertThat(res.total()).isEmpty();
    assertThat(LogSearchResult.of(List.of()).total()).isEqualTo(OptionalLong.empty());
    TailOptions tail = TailOptions.defaults();
    assertThat(tail.interval()).hasSeconds(1);
    tail.onError().accept(new RuntimeException("ignored"));
    assertThat(tail.withOnError(e -> {}).start()).isEmpty();
    WaitForLogOptions w = WaitForLogOptions.defaults();
    assertThat(w.timeout()).hasSeconds(30);
    assertThat(w.predicate().test(LogRecord.builder().build())).isTrue();
    assertThat(w.withPredicate(r -> false).predicate().test(LogRecord.builder().build())).isFalse();
    assertThat(WaitForLogOptions.of(java.time.Duration.ofMillis(5), null).interval()).hasSeconds(1);
    java.time.Duration two = java.time.Duration.ofSeconds(2);
    java.time.Duration one = java.time.Duration.ofSeconds(1);
    assertThat(tail.explicitInterval()).isEmpty();
    assertThat(tail.intervalOr(two)).isEqualTo(two);
    TailOptions oneSecond = new TailOptions(null, one, null);
    assertThat(oneSecond.explicitInterval()).contains(one);
    assertThat(oneSecond.withOnError(e -> {}).explicitInterval()).contains(one);
    assertThat(oneSecond.intervalOr(two)).isEqualTo(one);
    assertThat(w.explicitInterval()).isEmpty();
    assertThat(w.withPredicate(r -> true).intervalOr(two)).isEqualTo(two);
    assertThat(WaitForLogOptions.of(null, one).explicitInterval()).contains(one);
    assertThat(WaitForLogOptions.of(null, one).intervalOr(two)).isEqualTo(one);
  }

  @Test
  void searchOptions() {
    SearchOptions d = SearchOptions.defaults();
    assertThat(d.limit()).isEqualTo(100);
    assertThat(d.order()).isEqualTo(SortOrder.DESC);
    assertThat(d.start()).isEmpty();
    assertThat(d.end()).isEmpty();
    assertThat(d.cursor()).isEmpty();
    Instant s = Instant.parse("2026-01-01T00:00:00Z");
    SearchOptions o =
        SearchOptions.builder()
            .start(s)
            .end(s.plusSeconds(1))
            .limit(5)
            .order(SortOrder.ASC)
            .cursor("c")
            .build()
            .toBuilder()
            .build();
    assertThat(o.start()).contains(s);
    assertThat(o.cursor()).contains("c");
    assertThat(SearchOptions.builder().start(s).end(s).build().end()).contains(s);
    assertThat(SearchOptions.builder().end(s).build().end()).contains(s);
    assertThatThrownBy(() -> SearchOptions.builder().limit(0).build())
        .isInstanceOf(ValidationException.class);
    assertThatThrownBy(() -> SearchOptions.builder().start(s).end(s.minusSeconds(1)).build())
        .isInstanceOf(ValidationException.class);
  }
